            ],
            gearPacks: [
                { id: 'assault', name: '突击手入门包', cost: 8, description: '一套基础的战斗装备，适合喜欢正面冲突的幸存者。包含: 1x AK-74U, 2x 5.45mm弹匣(30发), 1x 军用绷带。' },
                { id: 'medic', name: '医疗兵补给箱', cost: 6, description: '大量的医疗物资，让你和你的队友能在战斗后迅速恢复。包含: 1x IFAK急救包, 3x 军用绷带, 2x 止痛药, 1x 抗生素。' },
                { id: 'scout', name: '潜行者工具组', cost: 7, description: '专注于隐秘行动和侦察的装备。包含: 1x 带消音器的手枪, 1x 备用弹匣, 1x 开锁器, 1x 望远镜。' },
                { id: 'survivalist', name: '生存主义者套装', cost: 5, description: '一套实用的野外生存工具，适合在丛林中自给自足。包含: 1x 消防斧, 1x 军用水壶, 2x MRE口粮, 1x 打火机。' },
                { id: 'heavy', name: '重装开局', cost: 10, description: '牺牲机动性换取强大的防护。包含: 1x PACA软质甲, 1x Kiver头盔, 1x 霰弹枪, 10x 12ga鹿弹。' },
                { id: 'marksman', name: '猎人补给', cost: 8, description: '适合中远距离交战。包含: 1x Mosin步枪, 20x 7.62x54mmR子弹, 1x 基础光学瞄具。' },
                { id: 'technician', name: '技师工具箱', cost: 6, description: '用于修理和改造的专业工具。包含: 1x 枪械修理工具, 1x 电子元件套组, 2x 胶带, 1x 多功能工具钳。' },
                { id: 'looter', name: '拾荒者之梦', cost: 4, description: '一个巨大的背包和撬棍，让你能带回更多战利品。包含: 1x 大型登山包, 1x 撬棍, 1x 能量棒。' },
                { id: 'barebones', name: '赤手空拳', cost: 2, description: '只有最基础的生存保障，挑战极限。包含: 1x 战斗匕首, 1x 瓶装水。' },
                { id: 'demolition', name: '爆破专家包', cost: 7, description: '用于制造混乱和打开通路。包含: 2x F1手榴弹, 1x 烟雾弹, 1x 简易爆炸物制作材料。' },
                { id: 'trapper', name: '陷阱猎人包', cost: 6, description: '专注于区域封锁和伏击。包含: 1x 捕兽夹, 2x 绊线式信号弹, 1x 战斗匕首。' },
                { id: 'nightstalker', name: '夜行者工具包', cost: 9, description: '为黑夜中的行动提供巨大优势。包含: 1x 带简易消音器的手枪, 1x 备用弹匣, 2x 化学荧光棒。' },
                { id: 'gambler', name: '赌徒的集装箱', cost: 1, description: '你只携带一个沉重的、密封的金属箱。在游戏开始时，AI将为你随机生成箱内的物品——可能是一把改装过的步枪，也可能只是一双发霉的靴子。命运的选择。' },
                { id: 'zone_sweeper', name: '辐射区清道夫包', cost: 7, description: '(仅限人类世界) 适用于探索危险区域的基础装备。包含: 1x 基础防毒面具, 2x 碘化钾片, 1x 盖革计数器 (低耐久度)。' }
            ],
            companions: [
                { id: 'guardian', name: '坚毅的守护者', cost: 12, description: '一位经验丰富的前军人，枪法精准，战术可靠...', skills: {'轻武器': '胜任者', '体能': '老兵', '认知': '新手'} },
                { id: 'scout', name: '灵巧的斥候', cost: 10, description: '一位敏捷的侦察兵，擅长潜行和规避危险...', skills: {'潜行': '老兵', '认知': '胜任者', '轻武器': '新手'} },
                { id: 'medic', name: '仁慈的医生', cost: 11, description: '一位心地善良的医疗专家，总是不忍心看到他人受苦...', skills: {'急救': '老兵', '认知': '新手', '制作': '胜任者'} },
                { id: 'technician', name: '博学的技师', cost: 10, description: '一位知识渊博的技术专家，能修理和改造设备...', skills: {'机械学': '老兵', '电子学': '胜任者', '制作': '新手'} },
                { id: 'brute', name: '狂暴的斗士', cost: 13, description: '一个沉默寡言的战斗机器，只相信手中的近战武器...', skills: {'近战': '老兵', '体能': '老兵', '潜行': '门外汉'} },
                { id: 'lone_wolf', name: '独狼行动', cost: 0, description: '你选择独自面对这一切。这很危险，但你将获得额外 2 点RP来强化自己。', skills: {} }
            ],
            skills: [ {id:"轻武器",name:"轻武器"},{id:"重武器",name:"重武器"},{id:"近战",name:"近战"},{id:"急救",name:"急救"},{id:"体能",name:"体能"},{id:"潜行",name:"潜行"},{id:"认知",name:"认知"},{id:"制作",name:"制作"},{id:"电子学",name:"电子学"},{id:"机械学",name:"机械学"} ],
            skillTiers: ["门外汉", "新手", "胜任者", "老兵", "精英"]
        };

        const CharacterCreator = {
            currentStep: 0,
            state: {},
            currentModal: null,

            init() {
                this.resetState();
                this.bindEvents();
                this.changeStep(1);
            },

            resetState() {
                this.state = {
                    worldline: null,
                    difficulty: null,
                    background: null,
                    quirks: [],
                    specialSkills: [],
                    skills: {},
                    gearPacks: [],
                    companions: [],
                    customBackground: '',
                    customGear: '',
                    customCompanion: '',
                    characterName: '',
                    baseRP: 0,
                    baseSkillPoints: 0,
                    totalRP: 0,
                    spentRP: 0,
                    totalSkillPoints: 0,
                    spentSkillPoints: 0,
                };
                DATA.skills.forEach(skill => {
                    this.state.skills[skill.id] = { level: 0, baseLevel: 0, userPoints: 0 };
                });
            },

            bindEvents() {
                const creatorMain = document.getElementById('creator-main');
                document.getElementById('btn-next').addEventListener('click', () => this.changeStep(this.currentStep + 1));
                document.getElementById('btn-prev').addEventListener('click', () => this.changeStep(this.currentStep - 1));
                document.getElementById('btn-deploy').addEventListener('click', () => this.deployToZone());

                creatorMain.addEventListener('mouseover', e => {
                    const item = e.target.closest('.selection-item');
                    if (item) this.updateDescriptionPanelOnHover(item);
                });

                creatorMain.addEventListener('mouseout', e => {
                     const item = e.target.closest('.selection-item');
                     if (item) this.updateDescriptionPanelForSelection();
                });

                creatorMain.addEventListener('click', (e) => {
                    const skillButton = e.target.closest('.skill-controls button');
                    if (skillButton) {
                        const skillId = skillButton.dataset.skill;
                        if (skillButton.dataset.action === 'upgrade') this.upgradeSkill(skillId);
                        if (skillButton.dataset.action === 'downgrade') this.downgradeSkill(skillId);
                        return;
                    }
                    const selectionItem = e.target.closest('.selection-item');
                    if (selectionItem) {
                        const list = selectionItem.closest('.selection-list');
                        if (list) this.handleSelection(list.id, selectionItem.dataset.id);
                        return;
                    }
                    const customButton = e.target.closest('.custom-button button');
                    if (customButton && !customButton.id.includes('background')) {
                        const modalType = customButton.id.replace('btn-custom-', '');
                        this.showCustomModal(modalType);
                    }
                });

                document.getElementById('modal-btn-confirm').addEventListener('click', () => this.confirmCustomModal());
                document.getElementById('modal-btn-cancel').addEventListener('click', () => this.hideCustomModal());
            },

            changeStep(step) {
                if (this.currentStep === 3 && step > 3) {
                    if (this.state.difficulty?.id === 'hell' && this.state.quirks.length === 0) {
                        alert('地狱难度必须选择至少一个“怪癖/弱点”才能继续！');
                        return;
                    }
                }
                if (step < 1 || step > 5) return;
                this.currentStep = step;
                this.renderStep(step);
            },

            renderStep(step) {
                const mainEl = document.getElementById('creator-main');
                mainEl.innerHTML = this.getStepHTML(step);
                document.getElementById('header-status').textContent = `步骤 ${step}/5 : ${this.getStepTitle(step)}`;
                this.updateUI();
            },

            getStepHTML(step) {
                switch(step) {
                    case 1: return `
                        <div class="creator-step active">
                          <h2 class="step-title">选择你要介入的现实维度</h2>
                          <div class="step-layout">
                              <div class="selection-column">
                                  <ul id="worldline-list" class="selection-list">${this.populateListHTML("worldlines")}</ul>
                              </div>
                              <div id="description-content" class="description-column"><p>请选择一个世界线...</p></div>
                          </div>
                        </div>`;
                    case 2: return `
                        <div class="creator-step active">
                          <h2 class="step-title">选择生存难度</h2>
                          <div class="step-layout">
                              <div class="selection-column">
                                  <ul id="difficulty-list" class="selection-list">${this.populateListHTML("difficulties")}</ul>
                              </div>
                              <div id="description-content" class="description-column"><p>请选择难度...</p></div>
                          </div>
                        </div>`;
                    case 3: return `
                        <div class="creator-step active">
                            <h2 class="step-title">构建个人档案</h2>
                            <div class="step-layout">
                                <div class="selection-column" style="flex: 1.5;">
                                    <div class="column-title">背景档案</div>
                                    <ul id="background-list" class="selection-list" style="max-height: 180px;">${this.populateListHTML("backgrounds")}</ul>
                                    <div class="column-title" style="margin-top: 15px;">怪癖/弱点 (可选, 多选)</div>
                                    <ul id="quirks-list" class="selection-list" style="max-height: 120px;">${this.populateListHTML("quirks")}</ul>
                                </div>
                                <div class="selection-column" style="flex: 2.5;">
                                     <div class="column-title">特殊技能 (多选)</div>
                                     <ul id="specialSkills-list" class="selection-list" style="max-height: 150px;">${this.populateListHTML("specialSkills")}</ul>
                                     <div class="column-title" style="margin-top: 15px;">专长分配 (剩余升级点: <span id="skill-points-counter">0</span>)</div>
                                     <ul id="skill-allocation-list" class="selection-list"></ul>
                                </div>
                            </div>
                        </div>`;
                    case 4: return `
                        <div class="creator-step active">
                            <h2 class="step-title">准备部署物资</h2>
                            <div class="step-layout">
                                 <div class="selection-column">
                                    <div class="column-title">物资征用 (多选)</div>
                                    <ul id="gearPacks-list" class="selection-list">${this.populateListHTML("gearPacks")}</ul>
                                    <div class="custom-button"><button id="btn-custom-gear" class="interaction-btn" style="width: 100%;">自定义物资</button></div>
                                </div>
                                <div class="selection-column">
                                    <div class="column-title">同伴征召 (多选)</div>
                                    <ul id="companion-list" class="selection-list">${this.populateListHTML("companions")}</ul>
                                    <div class="custom-button"><button id="btn-custom-companion" class="interaction-btn" style="width: 100%;">自定义同伴</button></div>
                                </div>
                                <div id="description-content" class="description-column"><p>选择物资和同伴...</p></div>
                            </div>
                        </div>`;
                    case 5: return `
                        <div class="creator-step active">
                             <h2 class="step-title">最终确认</h2>
                             <div class="step-layout" style="flex-direction: column; align-items: center; gap: 30px;">
                                <div style="width: 80%;"><div class="column-title">请输入你的幸存者代号</div><input type="text" id="character-name-input" class="name-input" placeholder="幸存者..."></div>
                                <div class="description-column" style="width: 80%; flex-grow: 1;"><div class="column-title">最终档案确认</div><div id="final-summary-content" class="final-summary"></div></div>
                             </div>
                        </div>`;
                    default: return '';
                }
            },

            populateListHTML(dataKey) {
                if (!DATA[dataKey]) return `<li>Error: Data key "${dataKey}" not found.</li>`;

                return DATA[dataKey].map(item => {
                    let costHtml = '';
                    if (item.cost !== undefined) {
                        costHtml = `<span class="rp-cost">${item.cost} RP</span>`;
                    } else if (item.reward !== undefined) {
                        costHtml = `<span class="rp-reward">+${item.reward} RP</span>`;
                    }
                    return `<li class="selection-item" data-id="${item.id}" data-list-key="${dataKey}">${item.name} ${costHtml}</li>`;
                }).join('');
            },

            handleSelection(listId, selectedId) {
                const keyMap = { 
                    'worldline-list':   { stateKey: 'worldline',   type: 'single', dataKey: 'worldlines' }, 
                    'difficulty-list':  { stateKey: 'difficulty',  type: 'single', dataKey: 'difficulties' },
                    'background-list':  { stateKey: 'background',  type: 'single', dataKey: 'backgrounds' }, 
                    'quirks-list':      { stateKey: 'quirks',      type: 'multi',  dataKey: 'quirks' },
                    'specialSkills-list':{ stateKey: 'specialSkills', type: 'multi',dataKey: 'specialSkills' }, 
                    'gearPacks-list':   { stateKey: 'gearPacks',   type: 'multi',  dataKey: 'gearPacks' }, 
                    'companion-list':   { stateKey: 'companions',  type: 'multi',  dataKey: 'companions' } 
                };
                const config = keyMap[listId];
                if (!config) return;

                const { stateKey, type, dataKey } = config;

                if (type === 'single') {
                    this.state[stateKey] = DATA[dataKey].find(item => item.id === selectedId);
                } else if (type === 'multi') {
                    const list = this.state[stateKey];
                    const index = list.findIndex(item => item.id === selectedId);
                    if (index > -1) {
                        list.splice(index, 1);
                    } else {
                        const itemData = DATA[dataKey].find(item => item.id === selectedId);
                        if (stateKey === 'companions') {
                            if (selectedId === 'lone_wolf') {
                                list.length = 0; 
                            } else {
                                const loneWolfIndex = list.findIndex(c => c.id === 'lone_wolf');
                                if (loneWolfIndex > -1) list.splice(loneWolfIndex, 1);
                            }
                            list.push({...itemData, gender: '女性'});
                        } else {
                           list.push(itemData);
                        }
                    }
                }

                if (stateKey === 'worldline') this.onWorldlineSelect();
                if (stateKey === 'difficulty') this.onDifficultySelect();
                if (stateKey === 'background') {
                    this.onBackgroundSelect();
                    if (selectedId === 'custom') {
                        this.showCustomModal('background');
                    }
                }
                if (stateKey === 'companions') this.updateDynamicPoints();

                this.updateUI();
            },

            async onWorldlineSelect() {
                if (this.state.worldline.id === 'desire') {
                    this.state.companions.forEach(c => {
                        if (c.id !== 'lone_wolf') c.gender = '女性';
                    });
                }

                this.showLoader(`正在同步世界线: ${this.state.worldline.name}...`);
                try {
                    await this.configureWorldbook(this.state.worldline);
                    this.showLoader("同步完成！");
                    setTimeout(() => this.hideLoader(), 1000);
                } catch (error) {
                    alert(`世界书配置失败: ${error.message}`);
                    this.hideLoader();
                }
            },

            async onDifficultySelect() {
                this.state.baseRP = this.state.difficulty.baseRP;
                this.state.baseSkillPoints = this.state.difficulty.baseSkillPoints;
                this.updateDynamicPoints();
                this.showLoader(`正在应用难度设定: ${this.state.difficulty.name}...`);
                try {
                    await this.configureDifficultyLorebook(this.state.difficulty);
                    this.showLoader("难度设定已写入世界书！");
                    setTimeout(() => this.hideLoader(), 1000);
                } catch (error) {
                    alert(`世界书难度设定失败: ${error.message}`);
                    this.hideLoader();
                }
            },

            onBackgroundSelect() {
                if (this.state.background?.id !== 'custom') {
                    this.state.customBackground = '';
                }
                this.updateDynamicPoints();
                this.initializeSkills();
            },

            async configureWorldbook(worldline) {
                if (!worldline || !worldline.prefixes) return;
                const config = worldline.prefixes;
                await TavernHelper.updateWorldbookWith(LOREBOOK_NAME, entries => {
                    return entries.map(entry => {
                        let enabled = entry.enabled;
                        const comment = entry.name || entry.comment || '';
                        const shouldEnable = config.enable?.some(prefix => comment.startsWith(prefix));
                        const shouldDisable = config.disable?.some(prefix => comment.startsWith(prefix));

                        if (shouldDisable) enabled = false;
                        else if (shouldEnable) enabled = true;

                        return { ...entry, enabled: enabled };
                    });
                });
            },

            async configureDifficultyLorebook(difficulty) {
                if (!difficulty || !difficulty.lore) return;
                await TavernHelper.updateWorldbookWith(LOREBOOK_NAME, entries => {
                    const entryIndex = entries.findIndex(e => (e.name || e.comment || '') === LOREBOOK_DIFFICULTY_COMMENT);
                    if (entryIndex > -1) {
                        entries[entryIndex].content = difficulty.lore;
                    } else {
                        console.warn(`未在世界书 "${LOREBOOK_NAME}" 中找到难度条目: "${LOREBOOK_DIFFICULTY_COMMENT}"`);
                    }
                    return entries;
                });
            },

            initializeSkills() {
                const backgroundSkills = this.state.background?.skills || {};
                DATA.skills.forEach(skill => {
                    const baseLevel = backgroundSkills[skill.id] || 0;
                    this.state.skills[skill.id] = { 
                        level: baseLevel,
                        baseLevel: baseLevel,
                        userPoints: 0
                    };
                });
                this.updateUI();
            },

            upgradeSkill(skillId) {
                const skill = this.state.skills[skillId];
                if (!skill) return;
                const spentPoints = Object.values(this.state.skills).reduce((acc, s) => acc + s.userPoints, 0);
                const maxSkillLevel = DATA.skillTiers.length - 1;
                if (spentPoints < this.state.totalSkillPoints && skill.level < maxSkillLevel) {
                    skill.level++;
                    skill.userPoints++;
                    this.updateUI();
                }
            },

            downgradeSkill(skillId) {
                const skill = this.state.skills[skillId];
                if (!skill) return;
                if (skill.level > skill.baseLevel) {
                    skill.level--;
                    skill.userPoints--;
                    this.updateUI();
                }
            },

            renderSkillAllocation() {
                const listEl = document.getElementById('skill-allocation-list');
                if (!listEl) return;
                listEl.innerHTML = '';

                const spentPoints = Object.values(this.state.skills).reduce((acc, s) => acc + s.userPoints, 0);
                this.state.spentSkillPoints = spentPoints;

                const pointsRemaining = this.state.totalSkillPoints - this.state.spentSkillPoints;
                const counterEl = document.getElementById('skill-points-counter');
                if(counterEl) counterEl.textContent = pointsRemaining;

                const maxSkillLevel = DATA.skillTiers.length - 1;
                DATA.skills.forEach(skillInfo => {
                    const skillData = this.state.skills[skillInfo.id];
                    const itemEl = document.createElement('li');
                    itemEl.className = 'selection-item';
                    itemEl.innerHTML = `
                        <span class="skill-name">${skillInfo.name}</span>
                        <span class="skill-level">${DATA.skillTiers[skillData.level]}</span>
                        <div class="skill-controls">
                            <button data-skill="${skillInfo.id}" data-action="downgrade" ${skillData.level <= skillData.baseLevel ? 'disabled' : ''}>-</button>
                            <button data-skill="${skillInfo.id}" data-action="upgrade" ${pointsRemaining <= 0 || skillData.level >= maxSkillLevel ? 'disabled' : ''}>+</button>
                        </div>
                    `;
                    listEl.appendChild(itemEl);
                });
            },

            renderFinalSummary() {
                const contentEl = document.getElementById('final-summary-content');
                const nameInput = document.getElementById('character-name-input');
                if(!contentEl || !nameInput) return;

                nameInput.value = this.state.characterName;

                const companionsText = this.state.customCompanion ? '自定义同伴' : (this.state.companions.map(c=>c.name).join('、 ') || '无');
                const gearPacksText = this.state.customGear ? '自定义物资' : (this.state.gearPacks.map(g=>g.name).join('、 ') || '无');
                const backgroundName = this.state.customBackground ? '自定义背景' : (this.state.background ? this.state.background.name : '无');
                const specialSkillsText = this.state.specialSkills.map(s => s.name).join('、 ') || '无';
                const quirksText = this.state.quirks.map(q => q.name).join('、 ') || '无';

                contentEl.innerHTML = `
                    <p><b>世界线:</b> <span>${this.state.worldline ? this.state.worldline.name : '未选择'}</span></p>
                    <p><b>难度:</b> <span>${this.state.difficulty ? this.state.difficulty.name : '未选择'}</span></p>
                    <p><b>背景档案:</b> <span>${backgroundName}</span></p>
                    <p><b>怪癖/弱点:</b> <span>${quirksText}</span></p>
                    <p><b>特殊技能:</b> <span>${specialSkillsText}</span></p>
                    <p><b>初始物资:</b> <span>${gearPacksText}</span></p>
                    <p><b>初始同伴:</b> <span>${companionsText}</span></p>
                `;
            },

// 【最终修正版本】使用 generate 发送消息，并手动处理返回结果以刷新页面
            async deployToZone() {
                this.state.characterName = document.getElementById('character-name-input').value.trim() || '幸存者';
                this.showLoader(`正在生成创世简报...`);
                const prompt = this.formatFinalPrompt();

                this.showLoader(`正在联系AI...部署至隔离区...`);

                try {
                    // 1. 发送请求并捕获AI的完整回复
                    const aiResponse = await TavernHelper.generate({ user_input: prompt });

                    if (!aiResponse) {
                        throw new Error("AI未能生成有效的回复，返回内容为空。");
                    }

                    // 2. 获取或创建第0条消息（开局消息）
                    // 对于开局设置，操作第0条消息是标准做法。
                    let messages = await TavernHelper.getChatMessages(0);

                    // 检查聊天是否为空。如果是，则创建一条新消息。
                    if (!messages || messages.length === 0) {
                        // 使用 createChatMessages 创建开局消息并刷新
                        // 注意：这将创建一条新消息，如果聊天中已有内容，它们会被后推
                        await TavernHelper.createChatMessages([{
                            role: 'system', // 开局通常是系统消息
                            message: aiResponse,
                            data: {} // 确保有一个空的data对象供MVU写入
                        }], { refresh: 'all' });

                    } else {
                        // 如果聊天中已有第0条消息，则覆盖它
                        const messageZero = messages[0];
                        messageZero.message = aiResponse; // 用AI的回复覆盖消息内容
                        messageZero.data = {}; // 清空旧的变量数据，让MVU脚本重新初始化

                        // 3. 使用 setChatMessages 触发整个页面的刷新
                        // refresh: 'all' 会导致聊天记录从服务器重新加载，从而触发MVU脚本扫描并执行变量更新
                        await TavernHelper.setChatMessages([messageZero], { refresh: 'all' });
                    }

                    // 4. 操作成功，隐藏加载动画
                    this.hideLoader();

                } catch (error) {
                    // 您的错误处理逻辑被完整保留在这里
                    console.error("部署失败:", error);
                    alert(`部署失败: ${error.message}`);
                    this.hideLoader();
                }
            },

            formatFinalPrompt() {
                const { worldline, difficulty, background, quirks, specialSkills, skills, gearPacks, companions, customBackground, customGear, customCompanion, characterName } = this.state;

                const specialSkillsText = specialSkills.map(s => `- ${s.name}: ${s.description}`).join('\n') || '无';
                const quirksText = quirks.map(q => `- ${q.name}: ${q.description}`).join('\n') || '无';
                const gearPacksText = customGear ? customGear : (gearPacks.map(g => `- ${g.name}: ${g.description}`).join('\n') || '无');
                const companionsText = customCompanion ? customCompanion : (companions.map(c => {
                    if (c.id === 'lone_wolf') return `- ${c.name}: ${c.description}`;
                    return `- ${c.name} (${c.gender || '女性'}): ${c.description}`;
                }).join('\n') || '无');
                const skillLines = DATA.skills.map(skillInfo => {
                    const skillData = skills[skillInfo.id];
                    return `- ${skillInfo.name}: ${DATA.skillTiers[skillData.level]}`;
                }).join('\n');

                let variableUpdates = `<UpdateVariable>\n<Analysis>\n// GM指令：执行开局角色变量初始化。\n</Analysis>\n`;
                const backgroundName = this.state.customBackground ? '自定义背景' : (this.state.background ? this.state.background.name : '无');
                variableUpdates += `_.set('角色背景[0]', '${backgroundName.replace(/'/g, "\\'") }');//设置角色背景\n`;

                const skillBonusMap = [0, 10, 20, 35, 50];
                DATA.skills.forEach(skillInfo => {
                    const skillData = this.state.skills[skillInfo.id];
                    const bonus = skillBonusMap[skillData.level] || 0;
                    variableUpdates += `_.set('技能熟练度[0].${skillInfo.id}', { "等级": "${DATA.skillTiers[skillData.level]}", "点数": 0, "升级所需": 100, "检定加成": ${bonus} });//设置${skillInfo.name}技能等级\n`;
                });

                const physicalSkill = this.state.skills['体能'];
                const hpBonusMap = [0, 0.05, 0.10, 0.15, 0.25];
                const hpBonus = hpBonusMap[physicalSkill.level] || 0;
                const hpValues = { Head: 35, Neck: 30, Thorax: 85, Stomach: 70, LeftArm: 60, RightArm: 60, LeftLeg: 65, RightLeg: 65 };
                for (const [part, baseHp] of Object.entries(hpValues)) {
                    const finalHp = Math.round(baseHp * (1 + hpBonus));
                    variableUpdates += `_.set('${part}上限HP[0]', ${finalHp});//体能加成\n`;
                    variableUpdates += `_.set('${part}当前HP[0]', ${finalHp});//体能加成\n`;
                }

                variableUpdates += `</UpdateVariable>`;

                return `### **【AI指令：游戏系统设定注入 - 开局初始化】**

**角色：** 你是游戏 **《${worldline.name.includes("僵尸") ? "僵尸！荒岛/荒野求生！" : (worldline.name.includes("人类") ? "隔离区：残光" : "不做爱就无法逃离的岛屿！")}》** 的游戏主持人（Game Master/GM）。
**任务：** 严格遵守并执行以下开局设定，并进行变量初始化。

---
#### **幸存者档案**
- **代号:** ${characterName}
- **世界线:** ${worldline ? worldline.name : "未指定"}
- **难度等级:** ${difficulty ? difficulty.name : "未指定"}
- **背景:** ${customBackground || (background ? background.description : "无")}
- **怪癖/弱点:**
${quirksText}
- **特殊技能:**
${specialSkillsText}
- **初始技能等级:**
${skillLines}

#### **初始部署**
- **物资:**
${gearPacksText}
- **同伴:**
${companionsText}
---

**GM核心任务:**
1.  **剧情生成:** 基于以上所有设定，创作一段沉浸式的、电影级的开局剧情。**你的开场剧情必须无缝地引出幸存者本人，以及“初始部署”部分列出的【每一位】同伴。** 为列表中的每一位同伴都进行简要的外貌和行为描绘，确保他们都真实地出现在开场场景中。
2.  **变量初始化:** 基于以上内容进行完整变量初始化，首先设定身份，技能等级，特殊技能。最后基于等级与技能设定最大的HP与当前的HP等内容。

${variableUpdates}
`;
            },

            updateDynamicPoints() {
                if (!this.state.difficulty) {
                    this.state.totalRP = 0;
                    this.state.totalSkillPoints = 0;
                    return;
                }
                let rpBonus = 0;
                let skillPointBonus = 0;
                if(this.state.companions.some(c => c.id === 'lone_wolf')) rpBonus += 2;
                if(this.state.background?.id === 'nobody') skillPointBonus += 1;

                this.state.totalRP = this.state.baseRP + rpBonus;
                this.state.totalSkillPoints = this.state.baseSkillPoints + skillPointBonus;
            },

            updateUI() {
                this.calculateRP();
                this.updateRPTracker();
                this.updateSelections();
                this.updateDescriptionPanelForSelection();
                if (this.currentStep === 3) this.renderSkillAllocation();
                if (this.currentStep === 5) this.renderFinalSummary();
                this.updateNavButtons();
            },

            calculateRP() {
                let spent = 0;
                spent += this.state.specialSkills.reduce((acc, s) => acc + s.cost, 0);
                spent += this.state.gearPacks.reduce((acc, g) => acc + g.cost, 0);
                spent += this.state.companions.reduce((acc, c) => acc + c.cost, 0);
                let reward = this.state.quirks.reduce((acc, q) => acc + q.reward, 0);
                this.state.spentRP = spent - reward;
            },

            updateRPTracker() {
                const tracker = document.getElementById('rp-tracker');
                if (!tracker) return;
                const remainingRP = this.state.totalRP - this.state.spentRP;
                tracker.textContent = `征用点数: ${remainingRP} / ${this.state.totalRP}`;
                tracker.style.color = (remainingRP < 0) ? 'red' : 'var(--pip-boy-amber)';
            },

            updateSelections() {
                this.updateSelectionGroup('worldline-list', this.state.worldline);
                this.updateSelectionGroup('difficulty-list', this.state.difficulty);
                this.updateSelectionGroup('background-list', this.state.background);
                this.updateSelectionGroup('quirks-list', this.state.quirks);
                this.updateSelectionGroup('specialSkills-list', this.state.specialSkills);
                this.updateSelectionGroup('gearPacks-list', this.state.gearPacks);
                if (this.currentStep === 4) {
                    this.renderCompanionSelections();
                }
            },

            renderCompanionSelections() {
                const listEl = document.getElementById('companion-list');
                if (!listEl) return;
                listEl.querySelectorAll('.selection-item').forEach(item => {
                    const companionState = this.state.companions.find(c => c.id === item.dataset.id);
                    const isSelected = !!companionState;
                    item.classList.toggle('selected', isSelected);

                    const oldGenderSelector = item.querySelector('.gender-selector');
                    if (oldGenderSelector) oldGenderSelector.remove();

                    if (isSelected && companionState.id !== 'lone_wolf') {
                        const isDesireWorldline = this.state.worldline?.id === 'desire';
                        const selector = document.createElement('div');
                        selector.className = 'gender-selector';
                        selector.innerHTML = `
                            <label><input type="radio" name="gender-${companionState.id}" value="女性" ${companionState.gender === '女性' ? 'checked' : ''}> 女性</label>
                            <label><input type="radio" name="gender-${companionState.id}" value="男性" ${companionState.gender === '男性' ? 'checked' : ''} ${isDesireWorldline ? 'disabled' : ''}> 男性</label>
                        `;
                        item.appendChild(selector);

                        selector.addEventListener('change', e => {
                            const selectedCompanion = this.state.companions.find(c => c.id === item.dataset.id);
                            if (selectedCompanion) {
                                selectedCompanion.gender = e.target.value;
                            }
                        });
                    }
                });
            },

            updateSelectionGroup(listId, selectedItems) {
                const listEl = document.getElementById(listId);
                if (!listEl) return;
                listEl.querySelectorAll('.selection-item').forEach(item => {
                    const isSelected = Array.isArray(selectedItems)
                        ? selectedItems.some(s => s.id === item.dataset.id)
                        : selectedItems && item.dataset.id === selectedItems.id;
                    item.classList.toggle('selected', isSelected);
                });
            },

            updateDescriptionPanelOnHover(targetElement) {
                this.renderDescription(targetElement.dataset.id, targetElement.dataset.listKey);
            },

            updateDescriptionPanelForSelection() {
                const activeStep = document.querySelector('.creator-step.active');
                if (!activeStep) return;

                let lastSelectedItem = null;
                const singleSelectLists = ['worldline-list', 'difficulty-list', 'background-list'];

                for (const listId of singleSelectLists) {
                    const list = activeStep.querySelector(`#${listId}`);
                    if (list) {
                        const selected = list.querySelector('.selection-item.selected');
                        if (selected) {
                            lastSelectedItem = selected;
                            break; 
                        }
                    }
                }

                if (lastSelectedItem) {
                    this.renderDescription(lastSelectedItem.dataset.id, lastSelectedItem.dataset.listKey);
                } else {
                    const descEl = document.getElementById('description-content');
                    if (descEl) descEl.innerHTML = `<p>请做出选择或将鼠标悬停在选项上以查看详情...</p>`;
                }
            },

            renderDescription(id, dataKey) {
                const descEl = document.getElementById('description-content');
                if (!descEl || !dataKey) return;
                const item = DATA[dataKey]?.find(i => i.id === id);
                if (item) {
                    descEl.innerHTML = `<h3>${item.name}</h3><p>${item.description}</p>`;
                }
            },

            updateNavButtons() {
                const btnPrev = document.getElementById('btn-prev');
                const btnNext = document.getElementById('btn-next');
                const btnDeploy = document.getElementById('btn-deploy');

                btnPrev.disabled = this.currentStep <= 1;
                btnNext.style.display = this.currentStep === 5 ? 'none' : 'inline-block';
                btnDeploy.style.display = this.currentStep === 5 ? 'inline-block' : 'none';

                let canProceed = false;
                switch(this.currentStep) {
                    case 1: canProceed = !!this.state.worldline; break;
                    case 2: canProceed = !!this.state.difficulty; break;
                    case 3: 
                        canProceed = !!this.state.background;
                        if (this.state.difficulty?.id === 'hell' && this.state.quirks.length === 0) {
                            canProceed = false;
                        }
                        break;
                    case 4: canProceed = (this.state.totalRP - this.state.spentRP >= 0); break;
                    case 5: canProceed = true; break;
                }
                btnNext.disabled = !canProceed;
            },

            showLoader(text) {
                document.getElementById('loader-text').textContent = text;
                document.getElementById('loader').classList.add('active');
            },

            hideLoader() {
                document.getElementById('loader').classList.remove('active');
            },

            showCustomModal(type) {
                this.currentModal = type;
                const modal = document.getElementById('custom-modal');
                const title = document.getElementById('modal-title');
                const desc = document.getElementById('modal-description');
                const textarea = document.getElementById('modal-textarea');
                switch(type) {
                    case 'background':
                        title.textContent = "自定义背景故事";
                        desc.textContent = "请用自然语言详细描述你的背景...";
                        textarea.value = this.state.customBackground;
                        break;
                    case 'gear':
                        title.textContent = "自定义物资清单";
                        desc.textContent = "请列出你希望携带的初始物资...";
                        textarea.value = this.state.customGear;
                        break;
                    case 'companion':
                        title.textContent = "自定义同伴档案";
                        desc.textContent = "请详细描述你希望的同伴类型...";
                        textarea.value = this.state.customCompanion;
                        break;
                }
                modal.classList.add('active');
            },

            hideCustomModal() {
                 document.getElementById('custom-modal').classList.remove('active');
            },

            confirmCustomModal() {
                const textarea = document.getElementById('modal-textarea');
                switch(this.currentModal) {
                    case 'background':
                        this.state.customBackground = textarea.value;
                        this.state.background = DATA.backgrounds.find(b => b.id === 'custom');
                        if (this.state.background) {
                            this.state.background.description = textarea.value || '自定义背景';
                        }
                        this.initializeSkills();
                        this.updateDynamicPoints();
                        break;
                    case 'gear':
                        this.state.customGear = textarea.value.trim();
                        const existingGear = this.state.gearPacks.find(item => item.id === 'custom');
                        if (this.state.customGear) {
                            if (existingGear) {
                                existingGear.description = this.state.customGear;
                            } else {
                                this.state.gearPacks.push({ id: 'custom', name: '自定义物资', cost: 0, description: this.state.customGear });
                            }
                        } else {
                            this.state.gearPacks = this.state.gearPacks.filter(item => item.id !== 'custom');
                        }
                        break;
                    case 'companion':
                        this.state.customCompanion = textarea.value.trim();
                        const existingCompanion = this.state.companions.find(item => item.id === 'custom');
                        if (this.state.customCompanion) {
                            if (existingCompanion) {
                                existingCompanion.description = this.state.customCompanion;
                            } else {
                                this.state.companions.push({ id: 'custom', name: '自定义同伴', cost: 0, description: this.state.customCompanion });
                            }
                        } else {
                            this.state.companions = this.state.companions.filter(item => item.id !== 'custom');
                        }
                        this.updateDynamicPoints();
                        break;
                }
                this.hideCustomModal();
                this.updateUI();
            },

            getStepTitle(step) {
                switch(step) {
                    case 1: return "选择世界线";
                    case 2: return "选择生存难度";
                    case 3: return "背景与专长";
                    case 4: return "物资与同伴";
                    case 5: return "最终确认";
                    default: return "";
                }
            },
        };

        document.addEventListener('DOMContentLoaded', () => {
            CharacterCreator.init();
        });
    })();
    </script>
</body>
</html>
