      #main-container::before { content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0; background: var(--pip-boy-bg-transparent); z-index: 1; }
      #main-container::after { content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0; background: linear-gradient(rgba(18,16,16,0) 50%, rgba(0,0,0,0.25) 50%), linear-gradient(90deg, rgba(255,0,0,0.06), rgba(0,255,0,0.02), rgba(0,0,255,0.06)); background-size: 100% 4px, 3px 100%; z-index: 2; pointer-events: none; opacity: 0.4; }
      .creator-header, .creator-footer { flex-shrink: 0; z-index: 3; padding: 10px 15px; border-bottom: 2px solid var(--pip-boy-green); display: flex; justify-content: space-between; align-items: center; }
      .creator-footer { border-top: 2px solid var(--pip-boy-green); border-bottom: none; margin-top: auto; flex-wrap: wrap; gap: 10px; /* --- 响应式修改: 允许换行 --- */ }
      .creator-main { flex-grow: 1; z-index: 3; position: relative; overflow: hidden; display: flex; /* --- 响应式修改: 添加flex以撑满高度 --- */ }
      .creator-step { width: 100%; height: 100%; padding: 15px; display: none; flex-direction: column; gap: 15px; overflow-y: auto; }
      .creator-step.active { display: flex; }
      .step-title { font-size: 1.5em; text-align: center; text-transform: uppercase; margin-bottom: 10px; border-bottom: 1px solid var(--pip-boy-green-dim); padding-bottom: 10px; }
      .step-layout { display: flex; gap: 20px; flex-grow: 1; min-height: 0; }
      .selection-column { flex: 1; display: flex; flex-direction: column; gap: 10px; border: 1px solid var(--pip-boy-green-dim); padding: 10px; background: rgba(0,0,0,0.2); min-height: 0; }
      .description-column { flex: 1.2; border: 1px solid var(--pip-boy-green-dim); padding: 15px; background: rgba(0,0,0,0.2); overflow-y: auto; font-size: 1em; line-height: 1.7; }
      .column-title { font-size: 1.2em; border-bottom: 1px solid var(--pip-boy-green-dim); padding-bottom: 8px; margin-bottom: 10px; flex-shrink: 0; }
      .selection-list { list-style: none; overflow-y: auto; flex-grow: 1; padding-right: 5px; }
      .selection-item { padding: 8px 12px; border: 1px dashed var(--pip-boy-green-dim); margin-bottom: 8px; cursor: pointer; transition: all 0.2s ease; font-size: 0.95em; /* --- 响应式修改: 调整字号 --- */ }
      .selection-item:hover { background: rgba(57, 255, 20, 0.1); border-color: var(--pip-boy-green); }
      .selection-item.selected { background: var(--pip-boy-green); color: var(--pip-boy-bg); text-shadow: none; border-style: solid; font-weight: bold; }
      .custom-button { margin-top: 10px; text-align: center; flex-shrink: 0; }
      .description-content h3 { color: var(--pip-boy-amber); margin-bottom: 10px; }
      .description-content p { color: var(--pip-boy-green-dim); margin-bottom: 15px; }
      .rp-cost, .rp-reward { float: right; font-weight: bold; }
      .rp-cost { color: var(--pip-boy-amber); }
      .rp-reward { color: #14c9ff; }
      .skill-allocation-list .selection-item { display: flex; justify-content: space-between; align-items: center; padding: 8px 12px; }
      .skill-name { flex-basis: 100px; }
      .skill-level { flex-basis: 100px; font-weight: bold; }
      .skill-controls button { font-size: 1em; width: 28px; height: 28px; text-align: center; padding: 0; margin-left: 5px; background: transparent; border: 1px solid var(--pip-boy-green-dim); color: var(--pip-boy-green); cursor: pointer; }
      .skill-controls button:hover:not(:disabled) { background: var(--pip-boy-green); color: var(--pip-boy-bg); }
      .skill-controls button:disabled { opacity: 0.3; cursor: not-allowed; }
      .final-summary { line-height: 2; font-size: 1em; }
      .final-summary span { color: var(--pip-boy-amber); }
      .name-input { background: rgba(57, 255, 20, 0.05); border: 1px solid var(--pip-boy-green-dim); color: var(--pip-boy-green); padding: 10px 15px; font-size: 1.2em; width: 100%; font-family: inherit; text-align: center; }
      .interaction-btn { padding: 10px 15px; background: transparent; border: 1px solid var(--pip-boy-green); color: var(--pip-boy-green); font-family: var(--pip-boy-font); font-size: 1em; cursor: pointer; transition: all 0.3s ease; text-transform: uppercase; }
      .interaction-btn:hover:not(:disabled) { background: var(--pip-boy-green); color: var(--pip-boy-bg); text-shadow: none; }
      .interaction-btn:disabled { opacity: 0.5; cursor: not-allowed; border-color: var(--pip-boy-green-dim); color: var(--pip-boy-green-dim); }
      .primary-btn { border-color: var(--pip-boy-amber); color: var(--pip-boy-amber); animation: pulse-amber 2s infinite; }
      @keyframes pulse-amber { 0% { box-shadow: 0 0 5px rgba(255, 184, 28, 0.4); } 50% { box-shadow: 0 0 15px rgba(255, 184, 28, 0.8); } 100% { box-shadow: 0 0 5px rgba(255, 184, 28, 0.4); } }
      .modal-overlay, .loader-overlay { position: absolute; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0, 0, 0, 0.8); display: none; justify-content: center; align-items: center; z-index: 1000; }
      .modal-overlay.active, .loader-overlay.active { display: flex; }
      .modal-content { background: var(--pip-boy-bg-modal); border: 2px solid var(--pip-boy-green); padding: 20px; width: 90%; /* --- 响应式修改: 宽度改为百分比 --- */ max-width: 600px; display: flex; flex-direction: column; gap: 15px; }
      .modal-content textarea { width: 100%; height: 150px; background: rgba(57, 255, 20, 0.05); border: 1px solid var(--pip-boy-green-dim); color: var(--pip-boy-green); font-family: inherit; font-size: 1em; padding: 10px; resize: vertical; }
      .modal-buttons { display: flex; justify-content: flex-end; gap: 15px; }
      .loader-content { font-size: 1.2em; display: flex; flex-direction: column; align-items: center; gap: 20px; }
      .spinner { width: 40px; height: 40px; border: 4px solid var(--pip-boy-green-dim); border-top-color: var(--pip-boy-green); border-radius: 50%; animation: spin 1s linear infinite; }
      @keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }
      ::-webkit-scrollbar { width: 8px; }
      ::-webkit-scrollbar-thumb { background: var(--pip-boy-green); border: 1px solid var(--pip-boy-bg); }
      ::-webkit-scrollbar-track { background: var(--pip-boy-bg); border: 1px solid var(--pip-boy-green-dim); }
      .gender-selector { padding-top: 8px; margin-top: 8px; border-top: 1px dashed var(--pip-boy-green-dim); font-size: 0.9em; }
      .gender-selector label { margin-right: 15px; cursor: pointer; }
      .gender-selector input[type="radio"] { margin-right: 5px; vertical-align: middle; }

      /* --- 响应式修改: 使用媒体查询适配小屏幕 (例如手机) --- */
      @media (max-width: 768px) {
        body { font-size: 14px; /* 在小屏幕上减小基础字号 */ }
        #main-container {
            border-left: none; /* 移除左右边框，使其完全贴合屏幕边缘 */
            border-right: none;
            box-shadow: none; /* 移除阴影 */
            margin: 0; /* 移除外边距 */
        }
        .creator-header h1 { font-size: 1.2em; } /* 缩小标题 */
        #rp-tracker { font-size: 1.1em !important; } /* 缩小点数显示 */

        .step-layout {
            flex-direction: column; /* 核心修改：将左右布局改为上下堆叠 */
            gap: 15px;
        }

        /* 强制让描述区域有最小高度，避免太扁 */
        .description-column {
            flex: none; /* 取消flex grow/shrink */
            height: 200px; /* 给一个固定的高度 */
            min-height: 150px;
            font-size: 0.95em;
        }

        .selection-column {
           min-height: 250px; /* 给选择区域一个最小高度 */
        }

        .creator-step {
            padding: 10px; /* 减小内边距 */
        }

        /* 底部按钮栏调整 */
        .creator-footer {
            justify-content: center; /* 居中按钮 */
            padding: 10px;
        }

        #btn-prev, #btn-next, #btn-deploy {
            flex-grow: 1; /* 让按钮平分宽度 */
        }

        #rp-tracker {
            width: 100%; /* 让点数显示独占一行 */
            text-align: center;
            order: -1; /* 将点数显示提到最前面 */
        }
      }
    </style>
</head>
<body>
    <div id="main-container">
        <div class="creator-header">
            <h1 id="header-title">隔离区档案终端</h1>
            <div id="header-status">等待初始化...</div>
        </div>
        <main id="creator-main" class="creator-main"></main>
        <div class="creator-footer">
            <button id="btn-prev" class="interaction-btn" disabled>上一步</button>
            <div id="rp-tracker" style="font-size: 20px;">征用点数: 0 / 0</div>
            <button id="btn-next" class="interaction-btn" disabled>下一步</button>
            <button id="btn-deploy" class="interaction-btn primary-btn" style="display: none;">部署至隔离区</button>
        </div>
    </div>

    <div id="custom-modal" class="modal-overlay">
        <div class="modal-content">
            <h2 id="modal-title" class="column-title">自定义</h2>
            <p id="modal-description"></p>
            <textarea id="modal-textarea"></textarea>
            <div class="modal-buttons">
                <button id="modal-btn-cancel" class="interaction-btn">取消</button>
                <button id="modal-btn-confirm" class="interaction-btn">确认</button>
            </div>
        </div>
    </div>

    <div id="loader" class="loader-overlay">
        <div class="loader-content">
            <div class="spinner"></div>
            <span id="loader-text">正在处理...</span>
        </div>
    </div>

    <script>
    /* 您的JavaScript代码无需修改，这里保持原样 */
    /* global TavernHelper */
    (function () {
        'use strict';

        // 【修正】API检查，确保generate可用
        if (typeof TavernHelper === 'undefined' || typeof TavernHelper.generate === 'undefined' || typeof TavernHelper.updateWorldbookWith === 'undefined') {
            document.addEventListener('DOMContentLoaded', () => {
                const container = document.getElementById('main-container') || document.body;
                container.innerHTML = '<h1 style="color: red; text-align: center; padding: 50px;">错误：SillyTavern 环境 API 未找到或版本过旧</h1><p style="color: grey; text-align: center;">请确保已安装并启用最新版 TavernHelper 扩展。</p>';
            });
            return;
        }

        const LOREBOOK_NAME = '隔离区日志';
        const LOREBOOK_DIFFICULTY_COMMENT = '【设定】难度';

        const DATA = {
            worldlines: [
                { id: 'zombie', name: '[维度] 僵尸世界', description: '在一个被未知病毒摧毁的世界里挣扎求生。你将面对成群的感染者、恐怖的变异生物和残酷的自然环境。', prefixes: { enable: ['【僵尸世界】', '【设定】'], disable: ['【人类世界】', '【瑟琴世界】'] }},
                { id: 'human', name: '[维度] 人类冲突', description: '在一个没有丧尸，但人性沦丧的孤岛上为生存而战。主要的威胁来自装备精良的敌对势力、狡猾的拾荒者。', prefixes: { enable: ['【人类世界】', '【设定】'], disable: ['【僵尸世界】', '【瑟琴世界】'] }},
                { id: 'desire', name: '[维度] 欲望孤岛', description: '（成人内容警告）你被困在一座只有异性幸存者的岛屿上。病毒强化了她们，也点燃了她们无尽的欲望。', prefixes: { enable: ['【瑟琴世界】', '【设定】'], disable: ['【僵尸世界】', '【人类世界】'] }}
            ],
            difficulties: [
                { id: 'god', name: '天神下凡', description: '你是天选之人，是这个残酷世界的唯一主角。资源对你来说唾手可得，敌人不过是你成神之路的垫脚石。', baseRP: 999, baseSkillPoints: 99, lore: '<难度>\n### **【AI指令：难度设定注入 - 天神下凡】**\n**GM核心任务:** 玩家选择了最高优先级的爽文模式。在所有未来的互动中，你必须：\n1.  **资源富足:** 大幅提高高价值物资（武器、药品、稀有材料）的发现概率。\n2.  **敌人削弱:** 降低非领主级敌人的战术协同性和命中率。\n3.  **叙事风格:** 叙事应充满电影化的爽快感，强调玩家的强大、果决与不可阻挡。玩家的行为应更容易获得NPC的正面反馈。\n</难度>' },
                { id: 'standard', name: '标准配给', description: '物资相对充裕，威胁等级经过调整。适合专注于剧情体验、初次接触本系统的幸存者。', baseRP: 25, baseSkillPoints: 4, lore: '<难度>\n### **【AI指令：难度设定注入 - 标准配给】**\n**GM核心任务:** 玩家选择了较宽松的生存模式。在所有未来的互动中，你必须：\n1.  **资源适中:** 基础生存物资（食物、水、简易医疗品）的发现概率有所提升。\n2.  **威胁可控:** 敌人的数量和攻击性会略微降低，给予玩家更多的反应时间。\n3.  **叙事平衡:** 保持世界观的残酷性，但允许玩家有更多的犯错空间。\n</难度>' },
                { id: 'realistic', name: '真实求生', description: '这是标准的生存挑战，资源有限，威胁致命。每一个选择都至关重要。', baseRP: 20, baseSkillPoints: 3, lore: '<难度>\n### **【AI指令：难度设定注入 - 真实求生】**\n**GM核心任务:** 玩家选择了标准的硬核生存模式。在所有未来的互动中，你必须：\n1.  **逻辑至上:** 严格遵循世界书中的所有硬核规则，包括物资稀缺性、敌人致命性、生理系统惩罚等。\n2.  **叙事中立:** 保持客观、写实的叙事风格。世界的反应是基于因果而非剧情需要。\n3.  **后果真实:** 玩家的每一个错误决策都必须导向其应有的负面后果，包括受伤、资源损失甚至死亡。\n</难度>' },
                { id: 'extreme', name: '极限挑战', description: '你开局处于劣势，物资极度稀缺，敌人也更具威胁。专为寻求挑战的废土老兵设计。', baseRP: 15, baseSkillPoints: 2, lore: '<难度>\n### **【AI指令：难度设定注入 - 极限挑战】**\n**GM核心任务:** 玩家选择了高难度生存模式。在所有未来的互动中，你必须：\n1.  **资源匮乏:** 大幅降低高价值物资的发现概率，食物和药品会更频繁地出现过期或损坏状态。\n2.  **敌人强化:** 敌人的感知范围、攻击欲望和战术能力都有所提升。\n3.  **环境严苛:** 天气变化更频繁，负面状态（如失温、感染）的后果更严重。\n</难度>' },
                { id: 'hell', name: '地狱难度', description: '你不仅一无所有，甚至身负枷锁。你必须选择至少一个“怪癖/弱点”才能开始。你的故事很可能在第一天就结束。', baseRP: 10, baseSkillPoints: 2, lore: '<难度>\n### **【AI指令：难度设定注入 - 地狱难度】**\n**GM核心任务:** 玩家选择了最残酷的生存模式。在所有未来的互动中，你必须将真实性推向极致：\n1.  **资源枯竭:** 物资极其罕见，几乎所有找到的容器都是空的。\n2.  **精英敌人:** 你将更频繁地遭遇高阶敌人，它们拥有世界书中所描述的全部能力。\n3.  **无情世界:** 任何微小的失误都可能导致连锁反应并最终死亡。世界不会给予任何仁慈。\n</难度>' }
            ],
            backgrounds: [
                { id: 'pmc', name: '前PMC士兵', description: '你曾为某个私人军事承包商效力，熟悉武器和战术。', skills: { '轻武器': 2, '体能': 1 } },
                { id: 'medic', name: '野外医生', description: '你拥有专业的医疗知识，能在恶劣条件下拯救生命。', skills: { '急救': 2, '认知': 1 } },
                { id: 'engineer', name: '勘探工程师', description: '你精通机械和电子设备，能让废铁重获新生。', skills: { '机械学': 2, '电子学': 1 } },
                { id: 'scavenger', name: '老练拾荒者', description: '你在这片废土上摸爬滚打了很久，懂得如何保持低调和发现价值。', skills: { '潜行': 2, '认知': 1 } },
                { id: 'hunter', name: '猎人', description: '丛林是你的家。你懂得如何追踪猎物，并利用自然。', skills: { '轻武器': 1, '潜行': 1, '制作': 1 } },
                { id: 'police', name: '前执法人员', description: '你曾是警察或联邦探员，拥有敏锐的观察力和处理危机的经验。', skills: { '认知': 2, '轻武器': 1 } },
                { id: 'athlete', name: '运动员', description: '你曾是职业或半职业运动员，拥有超越常人的体能和耐力。', skills: { '体能': 2, '近战': 1 } },
                { id: 'asset', name: '“公司”资产', description: '你曾为某个巨型企业执行秘密任务，精通渗透和信息处理。', skills: { '潜行': 1, '电子学': 1, '认知': 1 } },
                { id: 'nobody', name: '无名之辈', description: '你只是个普通人，没有任何专长，但这也意味着你有无限的可能。提供额外的1个专长升级点。', skills: {} },
                { id: 'custom', name: '>> 自定义背景 <<', description: '手动输入你的背景故事，技能将全部从零开始。', skills: {} }
            ],
            quirks: [
                { id: 'allergy', name: '过敏体质', reward: 1, description: '在丛林或沼泽地带，有一定几率会不受控制地打喷嚏，制造噪音并导致短时间的视野模糊。' },
                { id: 'chronic_pain', name: '慢性疼痛', reward: 1, description: '你的身体有旧伤。在“寒冷”或“湿透”状态下，会持续产生轻微的“疼痛(Pain)”效果，并缓慢降低士气。' },
                { id: 'addict', name: '瘾君子', reward: 2, description: '你开局就对“止痛药”或“香烟”有依赖性。每过一天不摄入成瘾品，就会出现戒断反应，导致“手部颤抖(Tremors)”和持续的士气下降。' },
                { id: 'loud_hands', name: '笨手笨脚', reward: 2, description: '你天生就不是个细致的人。搜刮、制作、换弹匣等所有精细操作的基础耗时增加25%。' },
                { id: 'illiterate', name: '文盲', reward: 3, description: '你无法通过阅读任何文件（书籍、手册、情报）来获得技能点或制作配方。你只能通过实践来学习。' },
                { id: 'glass_cannon', name: '玻璃大炮', reward: 3, description: '你的身体比常人脆弱。所有身体部位的最大生命值永久降低15%。' }
            ],
            specialSkills: [
                { id: 'gunslinger', name: '快枪手', cost: 5, description: '所有手枪和冲锋枪的换弹和瞄准速度相关的判定获得显著加成。切换到副武器不消耗时间。' },
                { id: 'weapon_specialist', name: '武器专家', cost: 5, description: '`机械学`技能视为比当前高一个等级（仅用于武器维修和改装判定），维修武器时消耗的零件更少。' },
                { id: 'melee_master', name: '近战大师', cost: 5, description: '所有近战攻击的伤害和冲击力提升25%，挥砍消耗的耐力降低。' },
                { id: 'grenadier', name: '掷弹兵', cost: 5, description: '投掷物（手榴弹、燃烧瓶）的投掷距离增加50%，并且落点更精准。可以制作简易爆炸陷阱。' },
                { id: 'marksman', name: '稳定射手', cost: 5, description: '使用步枪和狙击枪进行精确瞄准时，耐力消耗降低，武器晃动减小，受“疼痛”状态影响的精准度惩罚降低。' },
                { id: 'scav_eye', name: '拾荒之眼', cost: 5, description: '所有搜刮相关的`认知`判定获得显著加成。有小概率在已被搜刮过的容器中发现遗漏的物品。' },
                { id: 'iron_stomach', name: '野外美食家', cost: 5, description: '食用过期或未完全煮熟的食物时，进行“疾病抵抗”判定的成功率大幅提高。从烹饪食物中获得的士气恢复效果加倍。' },
